/** Contribution 2014 : Artificier arrondit sa moitié au supérieur, les demi-lanceurs ordinaires au inférieur. */
function spellcastingContribution(classId, level, type) {
  if (!Number.isInteger(level) || level < 0 || level > 20) throw new Error("Niveau de classe invalide.");
  if (classId === "artificer") return Math.ceil(level / 2);
  return type === "full" ? level : type === "half" ? Math.floor(level / 2) : type === "third" ? Math.floor(level / 3) : 0;
}

