  if (value.schemaVersion !== RULE_CONTRACT_VERSION) diagnostics.push(ruleDiagnostic("dependency.version", `${path}.schemaVersion`, "Version du contrat de dépendance incompatible."));
  for (const key of ["sourceKey", "referenceId", "revision", ...(value.acquisitionId === undefined ? [] : ["acquisitionId"])]) if (typeof value[key] !== "string" || !value[key].trim() || value[key].length > 500) diagnostics.push(ruleDiagnostic("dependency.identity", `${path}.${key}`, "Identité de dépendance invalide."));
  if (value.prerequisite !== undefined) diagnostics.push(...validateRulePrerequisiteSchema(value.prerequisite, `${path}.prerequisite`));
