function disposePortraitEditor() {
  portraitSession?.upload?.dispose();
  portraitSession = null;
}

function openPortraitEditor() {
  disposePortraitEditor();
  const character = ui.wizard?.draft || activeCharacter(), entry = portraitEntryOf(character);
  portraitSession = { character: clone(character), wizard: ui.wizard, selected: clone(character.portrait || null), family: portraitFamilyOf(character).id, sex: entry.sex, upload: null, crop: { x: 0.5, y: 0.5, zoom: 1 }, busy: false, error: "" };
  if (character.portrait?.kind === "preset") portraitSession.family = entry.family;
  openModal("portrait");
}

