  if (d.climbSpeed) rows.push(["Escalade", formatMeters(d.climbSpeed)]);
  if (d.burrowSpeed) rows.push(["Fouissement", formatMeters(d.burrowSpeed)]);
  if (d.wildShape?.senses.length) rows.push(["Sens de la forme (source EN)", d.wildShape.senses.join(" ; ")]);
